      observations: {
        heading: "Notas de fidelidade canônica",
        items: [
          "Sûza não é um antigo nome élfico. É uma forma do nome do Condado na língua original dos Hobbits, representada por Tolkien por meio do inglês *Shire*.",
          "O Condado não foi simplesmente concedido aos Hobbits como um reino independente. Sua ocupação foi autorizada pelo rei de Arthedain, e a autonomia hobbit desenvolveu-se ao longo dos séculos.",
          "A Terra dos Buques não constitui uma quinta Quarta. É um território associado ao Condado, com história e costumes próprios.",
          "O Condado não ficou completamente isolado dos perigos. Houve ataques de Orcs, a proteção dos Guardiões do Norte e, finalmente, a ocupação durante a Guerra do Anel.",
          "Para a história, os costumes e a geografia do Condado, o Prólogo de *O Senhor dos Anéis* é a fonte mais importante. Para sua transformação durante a Guerra do Anel, os capítulos *A Devastação do Condado* e *Os Portos Cinzentos* são fundamentais.",
        ],
      },
