      observations: {
        heading: "Notas de fidelidade canônica",
        items: [
          "A casa não possui outro nome próprio confirmado. Iarwain Ben-adar é um nome de Tom Bombadil, não da residência.",
          "Não há uma data conhecida para sua construção. Sua existência é documentada na Terceira Era, mas não é possível estabelecer sua origem.",
          "Tom e Fruta d'Ouro acolheram os quatro Hobbits em setembro de 3018, depois do encontro com o Velho Salgueiro.",
          "Tom colocou o Um Anel no dedo sem desaparecer, e conseguiu perceber Frodo quando este utilizou o Anel.",
          "Isso não significa que o Um Anel fosse absolutamente incapaz de afetar qualquer circunstância relacionada a Tom. O Conselho de Elrond deixa claro que ele não seria um guardião seguro do objeto.",
          "A natureza exata de Tom Bombadil e Fruta d'Ouro não é explicada definitivamente por Tolkien.",
          "A casa não deve ser descrita como um domínio mágico ilimitado ou invulnerável. Sua segurança está associada aos moradores e à relação singular que mantêm com aquela região.",
          "O capítulo *Na Casa de Tom Bombadil*, de *A Sociedade do Anel*, é a principal fonte para descrever a residência e os acontecimentos vividos pelos Hobbits. As cartas de Tolkien ajudam a interpretar o personagem, mas não substituem a narrativa publicada.",
        ],
      },
