          "Valle é a tradução portuguesa de Dale, nome utilizado no original inglês.",
          "Cidade dos Sinos é uma designação descritiva, não um nome oficial distinto registrado por Tolkien.",
          "A data de fundação da antiga Valle é desconhecida. Não deve ser confundida com a restauração do reino em 2944.",
