                "Livro V, capítulo 6 — **A Batalha dos Campos do Pelennor**: Chegada dos Rohirrim, morte de Théoden, derrota do Rei-bruxo e intervenção de Aragorn.",
                "Livro V, capítulo 7 — **A Pira de Denethor**: Morte do Regente e salvamento de Faramir.",
